-- ============================================================================
-- Vitalis Health Group - Snowflake
-- Private health insurance, private hospital and dental clinic data for
-- Vitalis Health Group, headquartered in Melbourne with hospitals and clinics
-- in New Zealand and Singapore. One schema per business, each with bronze,
-- silver and gold tables.
-- Generated by data/generator (make data). Run the whole file top to bottom;
-- it can be re-run and replaces the tables each time.
-- Dates are relative to the day the script runs, so 'today' and 'this month'
-- always have data. All people, companies and identifiers are fictional.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Setup
-- Tables are created in the current database: select your own database
-- first (the database picker in the worksheet or DBeaver, or
-- USE DATABASE <your database>), for example vitalis. Snowflake stops
-- the script if no database is selected. Needs a role that can create
-- schemas in it and a warehouse (USE WAREHOUSE <your warehouse>).
-- Unquoted names are stored in upper case.
-- ----------------------------------------------------------------------------

CREATE SCHEMA IF NOT EXISTS health_insurance
COMMENT = 'Vitalis Health Insurance';

CREATE SCHEMA IF NOT EXISTS hospitals
COMMENT = 'Vitalis Hospitals';

CREATE SCHEMA IF NOT EXISTS dental
COMMENT = 'Vitalis Dental';

-- ============================================================================
-- Vitalis Health Insurance (health_insurance)
-- Private health insurance: members, policies with hospital and extras cover,
-- providers, claims and member contact notes. Source: the membership and
-- claims system (MemberCore).
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Bronze: raw extracts from the source systems, loaded as-is.
-- ----------------------------------------------------------------------------

-- bronze_members: Everyone covered by a policy: the primary member, partners
-- and dependants. Families share a Medicare card.
--   Columns of note:
--     relationship: PRIMARY, PARTNER or DEPENDANT
--     first_name: Person name
--     last_name: Person name
--     date_of_birth: PII: date of birth
--     email: PII: email
--     mobile_phone: PII: phone number
--     address_line: PII: street address
--     country: Raw country as entered: AU, AUS, Australia...
--     medicare_number: Highly sensitive: Medicare card number (Australian
--       members)
--     medicare_irn: Position on the Medicare card
--   Rows: 330

CREATE OR REPLACE TABLE health_insurance.bronze_members (
  member_id VARCHAR,
  policy_id VARCHAR,
  relationship VARCHAR COMMENT 'PRIMARY, PARTNER or DEPENDANT',
  first_name VARCHAR COMMENT 'Person name',
  last_name VARCHAR COMMENT 'Person name',
  date_of_birth DATE COMMENT 'PII: date of birth',
  gender VARCHAR,
  email VARCHAR COMMENT 'PII: email',
  mobile_phone VARCHAR COMMENT 'PII: phone number',
  address_line VARCHAR COMMENT 'PII: street address',
  suburb VARCHAR,
  state VARCHAR,
  postcode VARCHAR,
  country VARCHAR COMMENT 'Raw country as entered: AU, AUS, Australia...',
  medicare_number VARCHAR COMMENT 'Highly sensitive: Medicare card number (Australian members)',
  medicare_irn INT COMMENT 'Position on the Medicare card',
  joined_date DATE,
  member_status VARCHAR,
  _source_system VARCHAR,
  _batch_id VARCHAR
)
COMMENT = 'Everyone covered by a policy: the primary member, partners and dependants. Families share a Medicare card.';


-- bronze_policies: Health insurance policies: hospital cover, extras or both,
-- for a single, couple or family.
--   Columns of note:
--     debit_bsb: Financial: BSB
--     debit_account_number: Financial: account number
--     card_number: Financial: card number
--     rebate_tier: Sensitive: Australian Government rebate tier, which
--       depends on income
--   Rows: 153

CREATE OR REPLACE TABLE health_insurance.bronze_policies (
  policy_id VARCHAR,
  primary_member_id VARCHAR,
  product_code VARCHAR,
  membership_type VARCHAR,
  has_extras BOOLEAN,
  start_date DATE,
  end_date DATE,
  policy_status VARCHAR,
  monthly_premium NUMBER(10,2),
  currency VARCHAR,
  hospital_excess NUMBER(10,2),
  payment_method VARCHAR,
  debit_bsb VARCHAR COMMENT 'Financial: BSB',
  debit_account_number VARCHAR COMMENT 'Financial: account number',
  card_number VARCHAR COMMENT 'Financial: card number',
  rebate_tier VARCHAR COMMENT 'Sensitive: Australian Government rebate tier, which depends on income',
  _source_system VARCHAR,
  _batch_id VARCHAR
)
COMMENT = 'Health insurance policies: hospital cover, extras or both, for a single, couple or family.';


-- bronze_providers: Hospitals and extras providers that claims are made at,
-- including Vitalis' own hospitals and dental clinics.
--   Rows: 40

CREATE OR REPLACE TABLE health_insurance.bronze_providers (
  provider_id VARCHAR,
  provider_name VARCHAR,
  provider_type VARCHAR,
  is_vitalis_owned BOOLEAN,
  provider_number VARCHAR,
  suburb VARCHAR,
  state VARCHAR,
  postcode VARCHAR,
  country VARCHAR,
  _source_system VARCHAR,
  _batch_id VARCHAR
)
COMMENT = 'Hospitals and extras providers that claims are made at, including Vitalis\' own hospitals and dental clinics.';


-- bronze_claims: Hospital and extras claims for the last 12 months.
-- benefit_amount is empty while a claim is pending.
--   Columns of note:
--     claim_type: HOSPITAL or EXTRAS
--     diagnosis_code: Health information: ICD-10-AM diagnosis code for
--       hospital claims
--   Rows: 962

CREATE OR REPLACE TABLE health_insurance.bronze_claims (
  claim_id VARCHAR,
  policy_id VARCHAR,
  member_id VARCHAR,
  provider_id VARCHAR,
  service_date DATE,
  claim_type VARCHAR COMMENT 'HOSPITAL or EXTRAS',
  service_code VARCHAR,
  item_description VARCHAR,
  diagnosis_code VARCHAR COMMENT 'Health information: ICD-10-AM diagnosis code for hospital claims',
  charged_amount NUMBER(12,2),
  benefit_amount NUMBER(12,2),
  currency VARCHAR,
  claim_status VARCHAR,
  rejection_reason VARCHAR,
  lodgement_channel VARCHAR,
  lodged_at TIMESTAMP_NTZ,
  _source_system VARCHAR,
  _batch_id VARCHAR
)
COMMENT = 'Hospital and extras claims for the last 12 months. benefit_amount is empty while a claim is pending.';


-- bronze_member_interactions: Contact centre and retail centre notes about
-- members.
--   Columns of note:
--     staff_employee_id: Matches employee_id in the HR data
--     notes: Free text: health conditions, pregnancy, Medicare numbers,
--       bank details, addresses and phone numbers
--   Rows: 260

CREATE OR REPLACE TABLE health_insurance.bronze_member_interactions (
  interaction_id VARCHAR,
  member_id VARCHAR,
  interaction_ts TIMESTAMP_NTZ,
  channel VARCHAR,
