  _source_system VARCHAR,
  _batch_id VARCHAR
)
COMMENT = 'Contact centre and retail centre notes about members.';


-- ----------------------------------------------------------------------------
-- Silver: cleaned, typed and conformed. Built from bronze.
-- ----------------------------------------------------------------------------

-- silver_members: Members with tidied names, age and age band, gender, ISO
-- country, region and Medicare number digits only.

CREATE OR REPLACE TABLE health_insurance.silver_members
COMMENT = 'Members with tidied names, age and age band, gender, ISO country, region and Medicare number digits only.'
AS
WITH base AS (
  SELECT
    m.member_id,
    m.policy_id,
    m.relationship,
    INITCAP(TRIM(m.first_name)) AS first_name,
    INITCAP(TRIM(m.last_name)) AS last_name,
    m.date_of_birth,
    CAST(FLOOR(DATEDIFF(day, CAST(m.date_of_birth AS DATE), CAST(CURRENT_DATE AS DATE)) / 365.25) AS INT) AS age,
    CASE WHEN UPPER(TRIM(m.gender)) IN ('F', 'FEMALE') THEN 'F' WHEN UPPER(TRIM(m.gender)) IN ('M', 'MALE') THEN 'M' ELSE 'X' END AS gender,
    LOWER(TRIM(m.email)) AS email,
    m.mobile_phone,
    m.address_line,
    m.suburb,
    m.state,
    m.postcode,
    CASE WHEN UPPER(TRIM(m.country)) IN ('AU', 'AUS', 'AUSTRALIA') THEN 'AU' WHEN UPPER(TRIM(m.country)) IN ('NZ', 'NZL', 'NEW ZEALAND') THEN 'NZ' WHEN UPPER(TRIM(m.country)) IN ('SG', 'SGP', 'SINGAPORE') THEN 'SG' WHEN UPPER(TRIM(m.country)) IN ('GB', 'GBR', 'UK', 'UNITED KINGDOM') THEN 'GB' WHEN UPPER(TRIM(m.country)) IN ('US', 'USA', 'UNITED STATES') THEN 'US' ELSE UPPER(TRIM(m.country)) END AS country,
    REGEXP_REPLACE(m.medicare_number, '[^0-9]', '') AS medicare_number,
    m.medicare_irn,
    m.joined_date,
    UPPER(TRIM(m.member_status)) AS member_status
  FROM health_insurance.bronze_members m
)
SELECT
  base.*,
  CASE WHEN base.age < 18 THEN '0-17' WHEN base.age < 25 THEN '18-24' WHEN base.age < 35 THEN '25-34' WHEN base.age < 50 THEN '35-49' WHEN base.age < 65 THEN '50-64' ELSE '65+' END AS age_band,
  CASE WHEN base.country IN ('AU', 'NZ', 'SG', 'JP', 'IN', 'MY', 'ID', 'HK') THEN 'APAC' WHEN base.country IN ('GB', 'IE', 'DE', 'FR', 'NL', 'AE', 'ZA') THEN 'EMEA' WHEN base.country IN ('US', 'CA', 'MX', 'BR') THEN 'AMER' ELSE 'UNKNOWN' END AS region
FROM base;

-- silver_policies: Policies with product name, active flag, tenure, AUD
-- premiums and the primary member's region.

CREATE OR REPLACE TABLE health_insurance.silver_policies
COMMENT = 'Policies with product name, active flag, tenure, AUD premiums and the primary member\'s region.'
AS
WITH base AS (
  SELECT p.*, UPPER(TRIM(p.policy_status)) AS clean_status
  FROM health_insurance.bronze_policies p
)
SELECT
  p.policy_id,
  p.primary_member_id,
  p.product_code,
  CASE p.product_code WHEN 'HOSPITAL_GOLD' THEN 'Gold Hospital' WHEN 'HOSPITAL_SILVER' THEN 'Silver Hospital'
    WHEN 'HOSPITAL_BRONZE' THEN 'Bronze Hospital' WHEN 'HOSPITAL_BASIC' THEN 'Basic Hospital'
    WHEN 'EXTRAS_ONLY' THEN 'Extras Only' ELSE 'International Health Cover' END AS product_name,
  CASE WHEN p.product_code = 'EXTRAS_ONLY' THEN FALSE ELSE TRUE END AS has_hospital_cover,
  p.has_extras,
  p.membership_type,
  p.start_date,
  p.end_date,
  p.clean_status AS policy_status,
  CASE WHEN p.clean_status = 'ACTIVE' THEN TRUE ELSE FALSE END AS is_active,
  ROUND(DATEDIFF(day, CAST(p.start_date AS DATE), CAST(COALESCE(p.end_date, CURRENT_DATE) AS DATE)) / 365.25, 1) AS tenure_years,
  p.monthly_premium,
  p.currency,
  CAST(p.monthly_premium * CASE p.currency WHEN 'AUD' THEN 1.00 WHEN 'NZD' THEN 0.92 WHEN 'SGD' THEN 1.13 WHEN 'GBP' THEN 1.95 WHEN 'USD' THEN 1.52 WHEN 'EUR' THEN 1.66 END AS NUMBER(18,2)) AS monthly_premium_aud,
  CAST(p.monthly_premium * 12 * CASE p.currency WHEN 'AUD' THEN 1.00 WHEN 'NZD' THEN 0.92 WHEN 'SGD' THEN 1.13 WHEN 'GBP' THEN 1.95 WHEN 'USD' THEN 1.52 WHEN 'EUR' THEN 1.66 END AS NUMBER(18,2)) AS annual_premium_aud,
  p.hospital_excess,
  p.payment_method,
  p.debit_bsb,
  p.debit_account_number,
  p.card_number,
  p.rebate_tier,
  m.state,
  m.country,
  m.region
FROM base p
JOIN health_insurance.silver_members m ON m.member_id = p.primary_member_id;

-- silver_providers: Providers with region.

CREATE OR REPLACE TABLE health_insurance.silver_providers
COMMENT = 'Providers with region.'
AS
SELECT provider_id, provider_name, provider_type, is_vitalis_owned, provider_number, suburb, state, postcode, country,
       CASE WHEN country IN ('AU', 'NZ', 'SG', 'JP', 'IN', 'MY', 'ID', 'HK') THEN 'APAC' WHEN country IN ('GB', 'IE', 'DE', 'FR', 'NL', 'AE', 'ZA') THEN 'EMEA' WHEN country IN ('US', 'CA', 'MX', 'BR') THEN 'AMER' ELSE 'UNKNOWN' END AS region
FROM health_insurance.bronze_providers;

-- silver_claims: Claims without duplicates, with provider, gap, AUD amounts,
-- days to lodge and the member's region.

CREATE OR REPLACE TABLE health_insurance.silver_claims
COMMENT = 'Claims without duplicates, with provider, gap, AUD amounts, days to lodge and the member\'s region.'
AS
WITH deduplicated AS (
  -- The extract re-sends some claims: keep the latest copy of each.
  SELECT c.*, ROW_NUMBER() OVER (PARTITION BY c.claim_id ORDER BY c._batch_id DESC) AS rn
  FROM health_insurance.bronze_claims c
)
SELECT
  c.claim_id,
  c.policy_id,
  c.member_id,
  c.provider_id,
  pr.provider_name,
  pr.provider_type,
  pr.is_vitalis_owned AS is_vitalis_provider,
  c.service_date,
  CAST(DATE_TRUNC('MONTH', c.service_date) AS DATE) AS service_month,
  c.claim_type,
  c.service_code,
  c.item_description,
  c.diagnosis_code,
  c.charged_amount,
  c.benefit_amount,
  c.charged_amount - c.benefit_amount AS gap_amount,
  c.currency,
  CAST(c.charged_amount * CASE c.currency WHEN 'AUD' THEN 1.00 WHEN 'NZD' THEN 0.92 WHEN 'SGD' THEN 1.13 WHEN 'GBP' THEN 1.95 WHEN 'USD' THEN 1.52 WHEN 'EUR' THEN 1.66 END AS NUMBER(18,2)) AS charged_aud,
  CAST(c.benefit_amount * CASE c.currency WHEN 'AUD' THEN 1.00 WHEN 'NZD' THEN 0.92 WHEN 'SGD' THEN 1.13 WHEN 'GBP' THEN 1.95 WHEN 'USD' THEN 1.52 WHEN 'EUR' THEN 1.66 END AS NUMBER(18,2)) AS benefit_aud,
  CAST(c.charged_amount - c.benefit_amount * CASE c.currency WHEN 'AUD' THEN 1.00 WHEN 'NZD' THEN 0.92 WHEN 'SGD' THEN 1.13 WHEN 'GBP' THEN 1.95 WHEN 'USD' THEN 1.52 WHEN 'EUR' THEN 1.66 END AS NUMBER(18,2)) AS gap_aud,
  c.claim_status,
  c.rejection_reason,
  c.lodgement_channel,
  c.lodged_at,
  DATEDIFF(day, CAST(c.service_date AS DATE), CAST(c.lodged_at AS DATE)) AS days_to_lodge,
  p.product_code,
  m.age_band,
  m.gender,
  m.country,
  m.region
FROM deduplicated c
JOIN health_insurance.silver_members m ON m.member_id = c.member_id
JOIN health_insurance.silver_policies p ON p.policy_id = c.policy_id
JOIN health_insurance.silver_providers pr ON pr.provider_id = c.provider_id
WHERE c.rn = 1;

-- silver_member_interactions: Member contact notes with region.

CREATE OR REPLACE TABLE health_insurance.silver_member_interactions
COMMENT = 'Member contact notes with region.'
AS
SELECT i.interaction_id, i.member_id, i.interaction_ts, CAST(i.interaction_ts AS DATE) AS interaction_date, i.channel, i.reason,
       i.staff_employee_id, i.notes, m.country, m.region
FROM health_insurance.bronze_member_interactions i
JOIN health_insurance.silver_members m ON m.member_id = i.member_id;

-- ----------------------------------------------------------------------------
-- Gold: business-ready data products for reporting and AI. Built from silver.
-- ----------------------------------------------------------------------------

-- gold_claims_monthly: Claims by month, claim type, service and region:
-- claims, members claiming, charges, benefits paid, gap and rejections, in
-- AUD.

CREATE OR REPLACE TABLE health_insurance.gold_claims_monthly
COMMENT = 'Claims by month, claim type, service and region: claims, members claiming, charges, benefits paid, gap and rejections, in AUD.'
AS
SELECT
  service_month,
  claim_type,
  service_code,
  region,
  COUNT(*) AS claims,
  COUNT(DISTINCT member_id) AS members_claiming,
  SUM(charged_aud) AS charged_aud,
  SUM(CASE WHEN claim_status = 'PAID' THEN benefit_aud ELSE 0 END) AS benefits_paid_aud,
  SUM(CASE WHEN claim_status = 'PAID' THEN gap_aud ELSE 0 END) AS member_gap_aud,
  ROUND(CAST(SUM(CASE WHEN claim_status = 'PAID' THEN benefit_aud ELSE 0 END) AS NUMBER(18,4)) * 100 / NULLIF(SUM(CASE WHEN claim_status = 'PAID' THEN charged_aud ELSE 0 END), 0), 1) AS benefit_pct,
  SUM(CASE WHEN claim_status = 'REJECTED' THEN 1 ELSE 0 END) AS rejected_claims,
  SUM(CASE WHEN claim_status = 'PENDING' THEN 1 ELSE 0 END) AS pending_claims
FROM health_insurance.silver_claims
GROUP BY 1, 2, 3, 4;

-- gold_member_360: One row per member: cover, claims, benefits and gap in the
-- last 12 months, and the last contact note.

CREATE OR REPLACE TABLE health_insurance.gold_member_360
COMMENT = 'One row per member: cover, claims, benefits and gap in the last 12 months, and the last contact note.'
AS
WITH claims AS (
  SELECT
    member_id,
    COUNT(*) AS claims_12_months,
    SUM(CASE WHEN claim_type = 'HOSPITAL' THEN 1 ELSE 0 END) AS hospital_claims_12_months,
    SUM(CASE WHEN claim_status = 'PAID' THEN benefit_aud ELSE 0 END) AS benefits_paid_12_months_aud,
    SUM(CASE WHEN claim_status = 'PAID' THEN gap_aud ELSE 0 END) AS gap_12_months_aud,
    SUM(CASE WHEN claim_status = 'REJECTED' THEN 1 ELSE 0 END) AS rejected_claims_12_months
  FROM health_insurance.silver_claims
  WHERE service_date >= DATEADD(day, -365, CURRENT_DATE)
  GROUP BY member_id
),
latest_contact AS (
  SELECT member_id, interaction_date, reason, notes,
         ROW_NUMBER() OVER (PARTITION BY member_id ORDER BY interaction_ts DESC) AS rn
  FROM health_insurance.silver_member_interactions
)
SELECT
  m.member_id,
  m.policy_id,
  m.first_name,
  m.last_name,
  m.relationship,
  m.age,
  m.age_band,
  m.gender,
  p.product_code,
  p.product_name,
  p.membership_type,
  p.has_extras,
  p.policy_status,
  p.tenure_years,
  p.monthly_premium_aud,
  COALESCE(c.claims_12_months, 0) AS claims_12_months,
  COALESCE(c.hospital_claims_12_months, 0) AS hospital_claims_12_months,
  COALESCE(c.benefits_paid_12_months_aud, 0) AS benefits_paid_12_months_aud,
  COALESCE(c.gap_12_months_aud, 0) AS gap_12_months_aud,
  COALESCE(c.rejected_claims_12_months, 0) AS rejected_claims_12_months,
  l.interaction_date AS last_contact_date,
  l.reason AS last_contact_reason,
  l.notes AS last_contact_note,
  m.state,
  m.country,
  m.region
FROM health_insurance.silver_members m
JOIN health_insurance.silver_policies p ON p.policy_id = m.policy_id
LEFT JOIN claims c ON c.member_id = m.member_id
LEFT JOIN latest_contact l ON l.member_id = m.member_id AND l.rn = 1;

-- gold_cover_mix: Active policies by product, membership type, rebate tier and
-- region, with members covered and AUD premiums.

CREATE OR REPLACE TABLE health_insurance.gold_cover_mix
COMMENT = 'Active policies by product, membership type, rebate tier and region, with members covered and AUD premiums.'
AS
WITH covered AS (
  SELECT policy_id, COUNT(*) AS members FROM health_insurance.silver_members GROUP BY policy_id
)
SELECT
  p.product_code,
  p.product_name,
  p.membership_type,
  p.rebate_tier,
  p.region,
  COUNT(*) AS active_policies,
  SUM(c.members) AS members_covered,
  SUM(CASE WHEN p.has_extras THEN 1 ELSE 0 END) AS policies_with_extras,
  ROUND(AVG(p.monthly_premium_aud), 2) AS avg_monthly_premium_aud,
  SUM(p.annual_premium_aud) AS annual_premium_aud
FROM health_insurance.silver_policies p
JOIN covered c ON c.policy_id = p.policy_id
WHERE p.is_active
GROUP BY 1, 2, 3, 4, 5;

