-- ----------------------------------------------------------------------------
-- Silver: cleaned, typed and conformed. Built from bronze.
-- ----------------------------------------------------------------------------

-- silver_hospitals: Hospitals with region.

CREATE OR REPLACE TABLE hospitals.silver_hospitals
COMMENT = 'Hospitals with region.'
AS
SELECT hospital_id, hospital_name, suburb, city, state, postcode, country, CASE WHEN country IN ('AU', 'NZ', 'SG', 'JP', 'IN', 'MY', 'ID', 'HK') THEN 'APAC' WHEN country IN ('GB', 'IE', 'DE', 'FR', 'NL', 'AE', 'ZA') THEN 'EMEA' WHEN country IN ('US', 'CA', 'MX', 'BR') THEN 'AMER' ELSE 'UNKNOWN' END AS region, licensed_beds
FROM hospitals.bronze_hospitals;

-- silver_patients: Patients with tidied names, age and age band, gender, ISO
-- country, region and identifiers without spaces.

CREATE OR REPLACE TABLE hospitals.silver_patients
COMMENT = 'Patients with tidied names, age and age band, gender, ISO country, region and identifiers without spaces.'
AS
WITH base AS (
  SELECT
    p.patient_id,
    INITCAP(TRIM(p.first_name)) AS first_name,
    INITCAP(TRIM(p.last_name)) AS last_name,
    p.date_of_birth,
    CAST(FLOOR(DATEDIFF(day, CAST(p.date_of_birth AS DATE), CAST(CURRENT_DATE AS DATE)) / 365.25) AS INT) AS age,
    CASE WHEN UPPER(TRIM(p.gender)) IN ('F', 'FEMALE') THEN 'F' WHEN UPPER(TRIM(p.gender)) IN ('M', 'MALE') THEN 'M' ELSE 'X' END AS gender,
    LOWER(TRIM(p.email)) AS email,
    p.mobile_phone,
    p.address_line,
    p.suburb,
    p.state,
    p.postcode,
    CASE WHEN UPPER(TRIM(p.country)) IN ('AU', 'AUS', 'AUSTRALIA') THEN 'AU' WHEN UPPER(TRIM(p.country)) IN ('NZ', 'NZL', 'NEW ZEALAND') THEN 'NZ' WHEN UPPER(TRIM(p.country)) IN ('SG', 'SGP', 'SINGAPORE') THEN 'SG' WHEN UPPER(TRIM(p.country)) IN ('GB', 'GBR', 'UK', 'UNITED KINGDOM') THEN 'GB' WHEN UPPER(TRIM(p.country)) IN ('US', 'USA', 'UNITED STATES') THEN 'US' ELSE UPPER(TRIM(p.country)) END AS country,
    REGEXP_REPLACE(p.medicare_number, '[^0-9]', '') AS medicare_number,
    REGEXP_REPLACE(p.health_identifier, ' ', '') AS health_identifier,
    p.health_identifier_type,
    p.insurer_name,
    p.insurance_member_id,
    CASE WHEN p.insurance_member_id IS NULL THEN FALSE ELSE TRUE END AS is_vitalis_member,
    p.next_of_kin_name,
    p.next_of_kin_phone,
    p.gp_name
  FROM hospitals.bronze_patients p
)
SELECT
  base.*,
  CASE WHEN base.age < 18 THEN '0-17' WHEN base.age < 25 THEN '18-24' WHEN base.age < 35 THEN '25-34' WHEN base.age < 50 THEN '35-49' WHEN base.age < 65 THEN '50-64' ELSE '65+' END AS age_band,
  CASE WHEN base.country IN ('AU', 'NZ', 'SG', 'JP', 'IN', 'MY', 'ID', 'HK') THEN 'APAC' WHEN base.country IN ('GB', 'IE', 'DE', 'FR', 'NL', 'AE', 'ZA') THEN 'EMEA' WHEN base.country IN ('US', 'CA', 'MX', 'BR') THEN 'AMER' ELSE 'UNKNOWN' END AS region
FROM base;

-- silver_admissions: Admissions with length of stay, current inpatient and 28
-- day readmission flags, AUD charges and the patient's region.

CREATE OR REPLACE TABLE hospitals.silver_admissions
COMMENT = 'Admissions with length of stay, current inpatient and 28 day readmission flags, AUD charges and the patient\'s region.'
AS
WITH base AS (
  SELECT
    a.*,
    CAST(a.admitted_at AS DATE) AS admit_date,
    CAST(a.discharged_at AS DATE) AS discharge_date,
    LAG(a.discharged_at) OVER (PARTITION BY a.patient_id ORDER BY a.admitted_at) AS previous_discharged_at,
    LEAD(a.admitted_at) OVER (PARTITION BY a.patient_id ORDER BY a.admitted_at) AS next_admitted_at
  FROM hospitals.bronze_admissions a
)
SELECT
  a.admission_id,
  a.patient_id,
  a.hospital_id,
  h.hospital_name,
  a.admitted_at,
  a.admit_date,
  CAST(DATE_TRUNC('MONTH', a.admit_date) AS DATE) AS admit_month,
  a.discharged_at,
  a.discharge_date,
  CASE WHEN a.discharged_at IS NULL THEN TRUE ELSE FALSE END AS is_current_inpatient,
  DATEDIFF(day, CAST(a.admit_date AS DATE), CAST(COALESCE(a.discharge_date, CURRENT_DATE) AS DATE)) AS length_of_stay_days,
  CASE WHEN a.discharge_date = a.admit_date THEN TRUE ELSE FALSE END AS is_same_day,
  UPPER(TRIM(a.admission_type)) AS admission_type,
  a.ward,
  a.primary_diagnosis_code,
  a.diagnosis_description,
  a.procedure_description,
  CASE WHEN a.previous_discharged_at IS NOT NULL
        AND DATEDIFF(day, CAST(a.previous_discharged_at AS DATE), CAST(a.admitted_at AS DATE)) <= 28 THEN TRUE ELSE FALSE END AS is_readmission_28_days,
  CASE WHEN a.discharged_at IS NOT NULL AND a.next_admitted_at IS NOT NULL
        AND DATEDIFF(day, CAST(a.discharged_at AS DATE), CAST(a.next_admitted_at AS DATE)) <= 28 THEN TRUE ELSE FALSE END AS readmitted_within_28_days,
  a.attending_doctor_employee_id,
  a.payer_type,
  a.insurer_name,
  a.total_charge,
  a.currency,
  CAST(a.total_charge * CASE a.currency WHEN 'AUD' THEN 1.00 WHEN 'NZD' THEN 0.92 WHEN 'SGD' THEN 1.13 WHEN 'GBP' THEN 1.95 WHEN 'USD' THEN 1.52 WHEN 'EUR' THEN 1.66 END AS NUMBER(18,2)) AS total_charge_aud,
  a.discharge_destination,
  p.age_band,
  p.gender,
  p.country,
  p.region
FROM base a
JOIN hospitals.silver_hospitals h ON h.hospital_id = a.hospital_id
JOIN hospitals.silver_patients p ON p.patient_id = a.patient_id;

-- silver_clinical_notes: Clinical notes with the patient, hospital, ward and
-- region.

CREATE OR REPLACE TABLE hospitals.silver_clinical_notes
COMMENT = 'Clinical notes with the patient, hospital, ward and region.'
AS
SELECT n.note_id, n.admission_id, a.patient_id, a.hospital_id, a.ward, n.note_ts, n.author_role, n.author_employee_id,
       n.note_type, n.note_text, a.country, a.region
FROM hospitals.bronze_clinical_notes n
JOIN hospitals.silver_admissions a ON a.admission_id = n.admission_id;

-- silver_medication_orders: Medication orders with the patient, hospital, ward
-- and region.

CREATE OR REPLACE TABLE hospitals.silver_medication_orders
COMMENT = 'Medication orders with the patient, hospital, ward and region.'
AS
SELECT mo.order_id, mo.admission_id, a.patient_id, a.hospital_id, a.ward, mo.ordered_at, mo.medication, mo.dose, mo.route,
       mo.frequency, mo.is_controlled_drug, mo.prescriber_employee_id, mo.pharmacist_employee_id, a.country, a.region
FROM hospitals.bronze_medication_orders mo
JOIN hospitals.silver_admissions a ON a.admission_id = mo.admission_id;

-- ----------------------------------------------------------------------------
-- Gold: business-ready data products for reporting and AI. Built from silver.
-- ----------------------------------------------------------------------------

-- gold_daily_admissions: Admissions by day, hospital and patient region:
-- elective, emergency, maternity and same-day, with AUD charges.

CREATE OR REPLACE TABLE hospitals.gold_daily_admissions
COMMENT = 'Admissions by day, hospital and patient region: elective, emergency, maternity and same-day, with AUD charges.'
AS
SELECT
  admit_date,
  hospital_id,
  hospital_name,
  region,
  COUNT(*) AS admissions,
  SUM(CASE WHEN admission_type = 'ELECTIVE' THEN 1 ELSE 0 END) AS elective_admissions,
  SUM(CASE WHEN admission_type = 'EMERGENCY' THEN 1 ELSE 0 END) AS emergency_admissions,
  SUM(CASE WHEN admission_type = 'MATERNITY' THEN 1 ELSE 0 END) AS maternity_admissions,
  SUM(CASE WHEN is_same_day THEN 1 ELSE 0 END) AS same_day_admissions,
  SUM(total_charge_aud) AS total_charges_aud
FROM hospitals.silver_admissions
GROUP BY 1, 2, 3, 4;

-- gold_hospital_census: One row per hospital: patients in hospital now, in ICU
-- and mental health wards, and admitted and discharged today.

CREATE OR REPLACE TABLE hospitals.gold_hospital_census
COMMENT = 'One row per hospital: patients in hospital now, in ICU and mental health wards, and admitted and discharged today.'
AS
WITH inpatients AS (
  SELECT hospital_id, COUNT(*) AS current_inpatients,
         SUM(CASE WHEN ward = 'ICU' THEN 1 ELSE 0 END) AS icu_patients,
         SUM(CASE WHEN ward = 'MENTAL_HEALTH' THEN 1 ELSE 0 END) AS mental_health_patients
  FROM hospitals.silver_admissions
  WHERE is_current_inpatient
  GROUP BY hospital_id
),
admitted AS (
  SELECT hospital_id, COUNT(*) AS admitted_today FROM hospitals.silver_admissions WHERE admit_date = CURRENT_DATE GROUP BY hospital_id
),
discharged AS (
  SELECT hospital_id, COUNT(*) AS discharged_today FROM hospitals.silver_admissions WHERE discharge_date = CURRENT_DATE GROUP BY hospital_id
)
SELECT
  h.hospital_id,
  h.hospital_name,
  h.city,
  h.state,
  h.country,
  h.region,
  h.licensed_beds,
  COALESCE(i.current_inpatients, 0) AS current_inpatients,
  COALESCE(i.icu_patients, 0) AS icu_patients,
  COALESCE(i.mental_health_patients, 0) AS mental_health_patients,
  COALESCE(ad.admitted_today, 0) AS admitted_today,
  COALESCE(di.discharged_today, 0) AS discharged_today
FROM hospitals.silver_hospitals h
LEFT JOIN inpatients i ON i.hospital_id = h.hospital_id
LEFT JOIN admitted ad ON ad.hospital_id = h.hospital_id
LEFT JOIN discharged di ON di.hospital_id = h.hospital_id;

-- gold_length_of_stay: Discharges in the last 12 months by diagnosis, ward,
-- admission type and region: length of stay, 28 day readmissions and average
-- charge.

CREATE OR REPLACE TABLE hospitals.gold_length_of_stay
COMMENT = 'Discharges in the last 12 months by diagnosis, ward, admission type and region: length of stay, 28 day readmissions and average charge.'
AS
SELECT
  primary_diagnosis_code,
  diagnosis_description,
  ward,
  admission_type,
  region,
  COUNT(*) AS discharges_12_months,
  ROUND(AVG(length_of_stay_days), 1) AS avg_length_of_stay_days,
  MAX(length_of_stay_days) AS max_length_of_stay_days,
  SUM(CASE WHEN readmitted_within_28_days THEN 1 ELSE 0 END) AS readmissions_28_days,
  ROUND(CAST(SUM(CASE WHEN readmitted_within_28_days THEN 1 ELSE 0 END) AS NUMBER(18,4)) * 100 / NULLIF(COUNT(*), 0), 1) AS readmission_rate_pct,
  CAST(AVG(total_charge_aud) AS NUMBER(18,2)) AS avg_charge_aud
FROM hospitals.silver_admissions
WHERE NOT is_current_inpatient AND admit_date >= DATEADD(day, -365, CURRENT_DATE)
GROUP BY 1, 2, 3, 4, 5;

-- gold_patient_journey: One row per admission: patient, hospital, diagnosis,
-- length of stay, readmission flags, medications and the latest clinical note.

CREATE OR REPLACE TABLE hospitals.gold_patient_journey
COMMENT = 'One row per admission: patient, hospital, diagnosis, length of stay, readmission flags, medications and the latest clinical note.'
AS
WITH latest_note AS (
  SELECT admission_id, note_type, note_text, ROW_NUMBER() OVER (PARTITION BY admission_id ORDER BY note_ts DESC) AS rn
  FROM hospitals.silver_clinical_notes
),
medications AS (
  SELECT admission_id, COUNT(*) AS medications_ordered,
         SUM(CASE WHEN is_controlled_drug THEN 1 ELSE 0 END) AS controlled_drugs_ordered
  FROM hospitals.silver_medication_orders
  GROUP BY admission_id
)
SELECT
  a.admission_id,
  a.patient_id,
  p.first_name,
  p.last_name,
  p.age,
  p.age_band,
  p.gender,
  p.is_vitalis_member,
  a.hospital_name,
  a.admit_date,
  a.discharge_date,
  a.is_current_inpatient,
  a.length_of_stay_days,
  a.admission_type,
  a.ward,
  a.primary_diagnosis_code,
  a.diagnosis_description,
  a.procedure_description,
  a.is_readmission_28_days,
  a.readmitted_within_28_days,
  a.payer_type,
  a.total_charge_aud,
  COALESCE(mo.medications_ordered, 0) AS medications_ordered,
  COALESCE(mo.controlled_drugs_ordered, 0) AS controlled_drugs_ordered,
  n.note_type AS latest_note_type,
  n.note_text AS latest_note,
  a.country,
  a.region
FROM hospitals.silver_admissions a
JOIN hospitals.silver_patients p ON p.patient_id = a.patient_id
LEFT JOIN medications mo ON mo.admission_id = a.admission_id
LEFT JOIN latest_note n ON n.admission_id = a.admission_id AND n.rn = 1;

-- ============================================================================
-- Vitalis Dental (dental)
-- Dental clinics: clinics, patients, appointments, treatments and clinical
-- notes. Source: the practice management system (DentalPro).
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Bronze: raw extracts from the source systems, loaded as-is.
-- ----------------------------------------------------------------------------

-- bronze_clinics: Vitalis dental clinics.
--   Rows: 12

CREATE OR REPLACE TABLE dental.bronze_clinics (
  clinic_id VARCHAR,
  clinic_name VARCHAR,
  suburb VARCHAR,
  city VARCHAR,
  state VARCHAR,
  postcode VARCHAR,
  country VARCHAR,
  dental_chairs INT,
  _source_system VARCHAR,
  _batch_id VARCHAR
)
COMMENT = 'Vitalis dental clinics.';


-- bronze_dental_patients: Dental patients. Children have a guardian;
-- health_fund_member_id is a Vitalis member_id for Vitalis members.
--   Columns of note:
--     first_name: Person name
--     last_name: Person name
--     date_of_birth: PII: date of birth
--     email: PII: email
--     mobile_phone: PII: phone number
--     address_line: PII: street address
--     country: Raw country as entered: AU, AUS, Australia...
--     health_fund_member_id: Matches member_id in health_insurance for
--       Vitalis members
--     guardian_name: Person name: parent or guardian of a child patient
--     medical_alerts: Health information: allergies, medications, pregnancy
--       and conditions
--   Rows: 300

CREATE OR REPLACE TABLE dental.bronze_dental_patients (
  patient_id VARCHAR,
  first_name VARCHAR COMMENT 'Person name',
  last_name VARCHAR COMMENT 'Person name',
  date_of_birth DATE COMMENT 'PII: date of birth',
  gender VARCHAR,
  email VARCHAR COMMENT 'PII: email',
  mobile_phone VARCHAR COMMENT 'PII: phone number',
  address_line VARCHAR COMMENT 'PII: street address',
  suburb VARCHAR,
  state VARCHAR,
  postcode VARCHAR,
  country VARCHAR COMMENT 'Raw country as entered: AU, AUS, Australia...',
  health_fund VARCHAR,
  health_fund_member_id VARCHAR COMMENT 'Matches member_id in health_insurance for Vitalis members',
  guardian_name VARCHAR COMMENT 'Person name: parent or guardian of a child patient',
  medical_alerts VARCHAR COMMENT 'Health information: allergies, medications, pregnancy and conditions',
  home_clinic_id VARCHAR,
  registered_date DATE,
  _source_system VARCHAR,
  _batch_id VARCHAR
)
COMMENT = 'Dental patients. Children have a guardian; health_fund_member_id is a Vitalis member_id for Vitalis members.';


-- bronze_appointments: Appointments for the last 13 months and the next month.
--   Columns of note:
--     practitioner_employee_id: Matches employee_id in the HR data
--   Rows: 820

CREATE OR REPLACE TABLE dental.bronze_appointments (
  appointment_id VARCHAR,
  patient_id VARCHAR,
  clinic_id VARCHAR,
  practitioner_employee_id VARCHAR COMMENT 'Matches employee_id in the HR data',
  appointment_at TIMESTAMP_NTZ,
  duration_minutes INT,
  appointment_type VARCHAR,
  appointment_status VARCHAR,
  cancellation_reason VARCHAR,
  booking_channel VARCHAR,
  _source_system VARCHAR,
  _batch_id VARCHAR
)
COMMENT = 'Appointments for the last 13 months and the next month.';


-- bronze_treatments: Treatments by Australian Dental Association item number,
-- with the health fund benefit and what the patient paid.
--   Columns of note:
--     tooth_number: FDI tooth number
--   Rows: 1043

CREATE OR REPLACE TABLE dental.bronze_treatments (
  treatment_id VARCHAR,
  appointment_id VARCHAR,
  item_code VARCHAR,
  item_description VARCHAR,
  tooth_number INT COMMENT 'FDI tooth number',
  fee NUMBER(10,2),
  fund_benefit NUMBER(10,2),
  patient_paid NUMBER(10,2),
  currency VARCHAR,
  claimed_on_the_spot BOOLEAN,
  _source_system VARCHAR,
  _batch_id VARCHAR
)
COMMENT = 'Treatments by Australian Dental Association item number, with the health fund benefit and what the patient paid.';


-- bronze_dental_notes: Clinical notes written by the practitioner after an
-- appointment.
--   Columns of note:
--     note_text: Free text, health information: pregnancy, medications,
--       anxiety, names and phone numbers
--   Rows: 368

CREATE OR REPLACE TABLE dental.bronze_dental_notes (
  note_id VARCHAR,
  appointment_id VARCHAR,
  note_ts TIMESTAMP_NTZ,
  author_employee_id VARCHAR,
  note_text VARCHAR COMMENT 'Free text, health information: pregnancy, medications, anxiety, names and phone numbers',
  _source_system VARCHAR,
  _batch_id VARCHAR
)
COMMENT = 'Clinical notes written by the practitioner after an appointment.';


-- ----------------------------------------------------------------------------
-- Silver: cleaned, typed and conformed. Built from bronze.
-- ----------------------------------------------------------------------------

-- silver_clinics: Clinics with region.

CREATE OR REPLACE TABLE dental.silver_clinics
COMMENT = 'Clinics with region.'
AS
SELECT clinic_id, clinic_name, suburb, city, state, postcode, country, CASE WHEN country IN ('AU', 'NZ', 'SG', 'JP', 'IN', 'MY', 'ID', 'HK') THEN 'APAC' WHEN country IN ('GB', 'IE', 'DE', 'FR', 'NL', 'AE', 'ZA') THEN 'EMEA' WHEN country IN ('US', 'CA', 'MX', 'BR') THEN 'AMER' ELSE 'UNKNOWN' END AS region, dental_chairs
FROM dental.bronze_clinics;

-- silver_dental_patients: Patients with tidied names, age, age band, child
-- flag, gender, ISO country, region and Vitalis member flag.

CREATE OR REPLACE TABLE dental.silver_dental_patients
COMMENT = 'Patients with tidied names, age, age band, child flag, gender, ISO country, region and Vitalis member flag.'
AS
WITH base AS (
  SELECT
    p.patient_id,
    INITCAP(TRIM(p.first_name)) AS first_name,
    INITCAP(TRIM(p.last_name)) AS last_name,
    p.date_of_birth,
    CAST(FLOOR(DATEDIFF(day, CAST(p.date_of_birth AS DATE), CAST(CURRENT_DATE AS DATE)) / 365.25) AS INT) AS age,
    CASE WHEN UPPER(TRIM(p.gender)) IN ('F', 'FEMALE') THEN 'F' WHEN UPPER(TRIM(p.gender)) IN ('M', 'MALE') THEN 'M' ELSE 'X' END AS gender,
    LOWER(TRIM(p.email)) AS email,
    p.mobile_phone,
    p.address_line,
    p.suburb,
    p.state,
    p.postcode,
    CASE WHEN UPPER(TRIM(p.country)) IN ('AU', 'AUS', 'AUSTRALIA') THEN 'AU' WHEN UPPER(TRIM(p.country)) IN ('NZ', 'NZL', 'NEW ZEALAND') THEN 'NZ' WHEN UPPER(TRIM(p.country)) IN ('SG', 'SGP', 'SINGAPORE') THEN 'SG' WHEN UPPER(TRIM(p.country)) IN ('GB', 'GBR', 'UK', 'UNITED KINGDOM') THEN 'GB' WHEN UPPER(TRIM(p.country)) IN ('US', 'USA', 'UNITED STATES') THEN 'US' ELSE UPPER(TRIM(p.country)) END AS country,
    p.health_fund,
    p.health_fund_member_id,
    CASE WHEN p.health_fund = 'Vitalis Health Insurance' THEN TRUE ELSE FALSE END AS is_vitalis_member,
    p.guardian_name,
    p.medical_alerts,
    p.home_clinic_id,
    p.registered_date
  FROM dental.bronze_dental_patients p
)
SELECT
  base.*,
  CASE WHEN base.age < 18 THEN TRUE ELSE FALSE END AS is_child,
  CASE WHEN base.age < 18 THEN '0-17' WHEN base.age < 25 THEN '18-24' WHEN base.age < 35 THEN '25-34' WHEN base.age < 50 THEN '35-49' WHEN base.age < 65 THEN '50-64' ELSE '65+' END AS age_band,
  CASE WHEN base.country IN ('AU', 'NZ', 'SG', 'JP', 'IN', 'MY', 'ID', 'HK') THEN 'APAC' WHEN base.country IN ('GB', 'IE', 'DE', 'FR', 'NL', 'AE', 'ZA') THEN 'EMEA' WHEN base.country IN ('US', 'CA', 'MX', 'BR') THEN 'AMER' ELSE 'UNKNOWN' END AS region
FROM base;

-- silver_appointments: Appointments with clinic, clean status, future flag and
-- the patient's region.

CREATE OR REPLACE TABLE dental.silver_appointments
COMMENT = 'Appointments with clinic, clean status, future flag and the patient\'s region.'
AS
SELECT
  ap.appointment_id,
  ap.patient_id,
  ap.clinic_id,
  c.clinic_name,
  ap.practitioner_employee_id,
  ap.appointment_at,
  CAST(ap.appointment_at AS DATE) AS appointment_date,
  CASE WHEN CAST(ap.appointment_at AS DATE) > CURRENT_DATE THEN TRUE ELSE FALSE END AS is_future,
  ap.duration_minutes,
  ap.appointment_type,
  UPPER(TRIM(ap.appointment_status)) AS appointment_status,
  ap.cancellation_reason,
  ap.booking_channel,
  p.age_band,
  p.country,
  p.region
FROM dental.bronze_appointments ap
JOIN dental.silver_clinics c ON c.clinic_id = ap.clinic_id
JOIN dental.silver_dental_patients p ON p.patient_id = ap.patient_id;

-- silver_treatments: Treatments with item category, treatment date, AUD fees
-- and benefits, and the patient's region.

CREATE OR REPLACE TABLE dental.silver_treatments
COMMENT = 'Treatments with item category, treatment date, AUD fees and benefits, and the patient\'s region.'
AS
SELECT
  t.treatment_id,
  t.appointment_id,
  ap.patient_id,
  ap.clinic_id,
  ap.clinic_name,
  ap.appointment_date AS treatment_date,
  CAST(DATE_TRUNC('MONTH', ap.appointment_date) AS DATE) AS treatment_month,
  t.item_code,
  t.item_description,
  CASE WHEN t.item_code IN ('011', '012', '114', '121') THEN 'PREVENTIVE' WHEN t.item_code = '022' THEN 'DIAGNOSTIC'
       WHEN t.item_code IN ('311', '521', '522') THEN 'GENERAL' ELSE 'MAJOR' END AS item_category,
  t.tooth_number,
  t.fee,
  t.fund_benefit,
  t.patient_paid,
  t.currency,
  CAST(t.fee * CASE t.currency WHEN 'AUD' THEN 1.00 WHEN 'NZD' THEN 0.92 WHEN 'SGD' THEN 1.13 WHEN 'GBP' THEN 1.95 WHEN 'USD' THEN 1.52 WHEN 'EUR' THEN 1.66 END AS NUMBER(18,2)) AS fee_aud,
  CAST(t.fund_benefit * CASE t.currency WHEN 'AUD' THEN 1.00 WHEN 'NZD' THEN 0.92 WHEN 'SGD' THEN 1.13 WHEN 'GBP' THEN 1.95 WHEN 'USD' THEN 1.52 WHEN 'EUR' THEN 1.66 END AS NUMBER(18,2)) AS fund_benefit_aud,
  CAST(t.patient_paid * CASE t.currency WHEN 'AUD' THEN 1.00 WHEN 'NZD' THEN 0.92 WHEN 'SGD' THEN 1.13 WHEN 'GBP' THEN 1.95 WHEN 'USD' THEN 1.52 WHEN 'EUR' THEN 1.66 END AS NUMBER(18,2)) AS patient_paid_aud,
  t.claimed_on_the_spot,
  ap.country,
  ap.region
FROM dental.bronze_treatments t
JOIN dental.silver_appointments ap ON ap.appointment_id = t.appointment_id;

-- silver_dental_notes: Dental notes with patient, clinic and region.

CREATE OR REPLACE TABLE dental.silver_dental_notes
COMMENT = 'Dental notes with patient, clinic and region.'
AS
SELECT n.note_id, n.appointment_id, ap.patient_id, ap.clinic_id, n.note_ts, n.author_employee_id, n.note_text, ap.country, ap.region
FROM dental.bronze_dental_notes n
JOIN dental.silver_appointments ap ON ap.appointment_id = n.appointment_id;

-- ----------------------------------------------------------------------------
-- Gold: business-ready data products for reporting and AI. Built from silver.
-- ----------------------------------------------------------------------------

-- gold_clinic_daily: Appointments by day, clinic and patient region, including
-- the next month's bookings: completed, cancelled, no-shows and AUD fees.

CREATE OR REPLACE TABLE dental.gold_clinic_daily
COMMENT = 'Appointments by day, clinic and patient region, including the next month\'s bookings: completed, cancelled, no-shows and AUD fees.'
AS
WITH fees AS (
  SELECT appointment_id, SUM(fee_aud) AS fees_aud, SUM(fund_benefit_aud) AS fund_benefits_aud
  FROM dental.silver_treatments
  GROUP BY appointment_id
)
SELECT
  ap.appointment_date,
  ap.clinic_id,
  ap.clinic_name,
  ap.region,
  COUNT(*) AS appointments,
  SUM(CASE WHEN ap.appointment_status = 'COMPLETED' THEN 1 ELSE 0 END) AS completed,
  SUM(CASE WHEN ap.appointment_status = 'BOOKED' THEN 1 ELSE 0 END) AS booked,
  SUM(CASE WHEN ap.appointment_status = 'CANCELLED' THEN 1 ELSE 0 END) AS cancelled,
  SUM(CASE WHEN ap.appointment_status = 'NO_SHOW' THEN 1 ELSE 0 END) AS no_shows,
  ROUND(CAST(SUM(CASE WHEN ap.appointment_status = 'NO_SHOW' THEN 1 ELSE 0 END) AS NUMBER(18,4)) * 100 / NULLIF(SUM(CASE WHEN ap.appointment_status IN ('COMPLETED', 'NO_SHOW') THEN 1 ELSE 0 END), 0), 1) AS no_show_rate_pct,
  COALESCE(SUM(f.fees_aud), 0) AS fees_aud,
  COALESCE(SUM(f.fund_benefits_aud), 0) AS fund_benefits_aud
FROM dental.silver_appointments ap
LEFT JOIN fees f ON f.appointment_id = ap.appointment_id
GROUP BY 1, 2, 3, 4;

-- gold_treatment_mix: Treatments by month, category, item and region, with AUD
-- fees, fund benefits and what patients paid.

CREATE OR REPLACE TABLE dental.gold_treatment_mix
COMMENT = 'Treatments by month, category, item and region, with AUD fees, fund benefits and what patients paid.'
AS
SELECT
  treatment_month,
  item_category,
  item_code,
  item_description,
  region,
  COUNT(*) AS treatments,
  COUNT(DISTINCT patient_id) AS patients,
  SUM(fee_aud) AS fees_aud,
  SUM(fund_benefit_aud) AS fund_benefits_aud,
  SUM(patient_paid_aud) AS patient_paid_aud
FROM dental.silver_treatments
GROUP BY 1, 2, 3, 4, 5;

-- gold_patient_recall: One row per patient: last visit and check-up, next
-- booking, no-shows, medical alerts and whether they are due for a recall.

CREATE OR REPLACE TABLE dental.gold_patient_recall
COMMENT = 'One row per patient: last visit and check-up, next booking, no-shows, medical alerts and whether they are due for a recall.'
AS
WITH visits AS (
  SELECT
    patient_id,
    MAX(CASE WHEN appointment_status = 'COMPLETED' THEN appointment_date END) AS last_visit_date,
    MAX(CASE WHEN appointment_status = 'COMPLETED' AND appointment_type IN ('CHECK_UP', 'HYGIENE') THEN appointment_date END) AS last_check_up_date,
    MIN(CASE WHEN appointment_status = 'BOOKED' AND appointment_date >= CURRENT_DATE THEN appointment_date END) AS next_appointment_date,
    SUM(CASE WHEN appointment_status = 'NO_SHOW' THEN 1 ELSE 0 END) AS no_shows
  FROM dental.silver_appointments
  GROUP BY patient_id
)
SELECT
  p.patient_id,
  p.first_name,
  p.last_name,
  p.age,
  p.age_band,
  p.is_child,
  p.guardian_name,
  p.email,
  p.mobile_phone,
  p.health_fund,
  p.is_vitalis_member,
  p.medical_alerts,
  c.clinic_name AS home_clinic_name,
  v.last_visit_date,
  v.last_check_up_date,
  ROUND(DATEDIFF(day, CAST(v.last_check_up_date AS DATE), CAST(CURRENT_DATE AS DATE)) / 30.4, 1) AS months_since_check_up,
  v.next_appointment_date,
  COALESCE(v.no_shows, 0) AS no_shows,
  CASE WHEN v.next_appointment_date IS NULL
        AND (v.last_check_up_date IS NULL OR v.last_check_up_date < DATEADD(day, -183, CURRENT_DATE)) THEN TRUE ELSE FALSE END AS is_due_for_recall,
  p.country,
  p.region
FROM dental.silver_dental_patients p
LEFT JOIN dental.silver_clinics c ON c.clinic_id = p.home_clinic_id
LEFT JOIN visits v ON v.patient_id = p.patient_id;
